def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(x)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)
    if len(y) < p:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h
    def pred(train, n, alpha, beta):
        cycles = max(1, len(train) // p)
        width = min(3, cycles)
        shift = 0.0
        if cycles >= 2:
            shift = statistics.median(train[-p:]) - statistics.median(train[-2 * p:-p])
            window = train[-min(3 * p, len(train)):]
            center = statistics.median(window)
            mad = statistics.median([abs(v - center) for v in window])
            shift = max(-mad, min(mad, shift))
        out = []
        for k in range(n):
            phase = k % p
            vals = [train[len(train) - (j + 1) * p + phase] for j in range(width)]
            recent = vals[0]
            robust = statistics.median(vals)
            day = min(2, 1 + k // p)
            out.append(float(alpha * recent + (1.0 - alpha) * robust + beta * shift * day))
        return out
    def smape(actual, estimate):
        e = [200.0 * abs(a - b) / (abs(a) + abs(b)) for a, b in zip(actual, estimate) if abs(a) + abs(b) > 1e-12]
        return sum(e) / len(e) if e else 0.0
    folds = []
    for back in range(min(4, len(y) // p - 1), 0, -1):
        cut = len(y) - back * p
        if cut >= 2 * p:
            folds.append((y[:cut], y[cut:cut + p]))
    choices = [(a, b) for a in (0.0, 0.25, 0.5, 0.75, 1.0) for b in (0.0, 0.25, 0.5)]
    if folds:
        scored = []
        for alpha, beta in choices:
            errors = [smape(actual, pred(train, len(actual), alpha, beta)) for train, actual in folds]
            risk = max(errors) + 0.25 * statistics.median(errors)
            scored.append((risk, statistics.median(errors), alpha, beta))
        _, _, alpha, beta = min(scored)
    else:
        alpha, beta = 1.0, 0.0
    return pred(y, h, alpha, beta)
